"use client";

import { useEffect, useId, useRef, useState } from "react";

import { MessageIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { AssistantPanel, type PanelMessage } from "./ai-side-panel/assistant-panel";
import { DOC_PARAGRAPHS, DOC_TITLE, FREE_REPLY, type PanelReply, selectionReply, SUGGESTIONS } from "./ai-side-panel/data";
import { type PageSelection, PolicyPage } from "./ai-side-panel/policy-page";
import { SidebarIcon, UndoIcon } from "./icons";
import { answerSize } from "./shared/answer";
import { useWordStream } from "./shared/use-word-stream";

interface Applied {
  paragraphId: string;
  before: string;
  messageId: string;
}

const SWEEP_MS = 2600;

/**
 * A policy page with an assistant docked beside it and scoped to it. The
 * person asks about the page or a selected passage, reviews each proposed
 * edit as a word diff, applies it with one click and can undo it. Closing
 * the panel narrows the dock and the page glides back to the centre.
 */
export function AiSidePanel({ className }: { className?: string }) {
  const titleId = useId();
  const stream = useWordStream({ delay: 500 });

  const [paragraphs, setParagraphs] = useState(DOC_PARAGRAPHS);
  const [open, setOpen] = useState(true);
  const [messages, setMessages] = useState<PanelMessage[]>([]);
  const [liveId, setLiveId] = useState<string | null>(null);
  const [selection, setSelection] = useState<PageSelection | null>(null);
  const [quote, setQuote] = useState<PageSelection | null>(null);
  const [applied, setApplied] = useState<Applied | null>(null);
  const [sweep, setSweep] = useState<{ paragraphId: string; before: string } | null>(null);
  const [status, setStatus] = useState("");

  const counter = useRef(0);
  const panelRef = useRef<HTMLDivElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const reopenRef = useRef<HTMLButtonElement>(null);
  const focusAfterToggle = useRef(false);

  useEffect(() => {
    if (!sweep) return;
    const timer = setTimeout(() => setSweep(null), SWEEP_MS);
    return () => clearTimeout(timer);
  }, [sweep]);

  useEffect(() => {
    if (!focusAfterToggle.current) return;
    focusAfterToggle.current = false;
    (open ? closeRef : reopenRef).current?.focus();
  }, [open]);

  const toggle = (next: boolean) => {
    focusAfterToggle.current = true;
    setOpen(next);
  };

  const nextId = () => {
    counter.current += 1;
    return `m${counter.current}`;
  };

  const ask = (text: string, reply: PanelReply, quoted?: string) => {
    const assistantId = nextId();
    const before = reply.edit ? paragraphs.find((paragraph) => paragraph.id === reply.edit?.paragraphId)?.text : undefined;
    setMessages((list) => [
      ...list,
      { id: nextId(), role: "user", text, quote: quoted },
      { id: assistantId, role: "assistant", reply, before, editState: "pending" },
    ]);
    setLiveId(assistantId);
    stream.start(answerSize(reply.parts), () => setLiveId(null));
  };

  const send = (text: string) => {
    const target = quote ? paragraphs.find((paragraph) => paragraph.id === quote.paragraphId) : undefined;
    ask(text, target ? selectionReply(target) : FREE_REPLY, quote?.text);
    setQuote(null);
  };

  const stop = () => {
    const id = liveId;
    const cut = stream.shown;
    stream.stop();
    setLiveId(null);
    if (id) setMessages((list) => list.map((message) => (message.id === id && message.role === "assistant" ? { ...message, cut } : message)));
  };

  const setEditState = (id: string, editState: "applied" | "dismissed" | "undone") =>
    setMessages((list) => list.map((message) => (message.id === id && message.role === "assistant" ? { ...message, editState } : message)));

  const apply = (messageId: string) => {
    const message = messages.find((item) => item.id === messageId);
    if (!message || message.role !== "assistant" || !message.reply.edit) return;
    const { paragraphId, after } = message.reply.edit;
    const before = paragraphs.find((paragraph) => paragraph.id === paragraphId)?.text ?? "";
    setParagraphs((list) => list.map((paragraph) => (paragraph.id === paragraphId ? { ...paragraph, text: after } : paragraph)));
    setApplied({ paragraphId, before, messageId });
    setSweep({ paragraphId, before });
    setEditState(messageId, "applied");
    setStatus("Edit applied to the page.");
  };

  const undo = () => {
    if (!applied) return;
    setParagraphs((list) => list.map((paragraph) => (paragraph.id === applied.paragraphId ? { ...paragraph, text: applied.before } : paragraph)));
    setEditState(applied.messageId, "undone");
    setApplied(null);
    setSweep(null);
    setStatus("Edit undone.");
  };

  const askAboutSelection = () => {
    if (!selection) return;
    setQuote(selection);
    if (!open) setOpen(true);
    requestAnimationFrame(() => panelRef.current?.querySelector("textarea")?.focus());
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <h2 id={titleId} className="sr-only">
        {DOC_TITLE}, with Fern
      </h2>
      <div
        className={cn(
          "grid grid-cols-1 @3xl:h-[38rem] motion-safe:transition-all motion-safe:duration-300 motion-safe:ease-out",
          open ? "@3xl:grid-cols-[minmax(0,1fr)_22rem]" : "@3xl:grid-cols-[minmax(0,1fr)_0rem]",
        )}
      >
        <div className="relative flex min-h-0 min-w-0 flex-col">
          <div className="flex flex-wrap items-center justify-between gap-2 border-b border-border px-4 py-2.5">
            <Button variant="outline" size="sm" disabled={!selection} onClick={askAboutSelection}>
              <MessageIcon aria-hidden="true" className="size-4" />
              Ask about selection
            </Button>
            {open ? null : (
              <Button ref={reopenRef} variant="outline" size="sm" onClick={() => toggle(true)}>
                <SidebarIcon aria-hidden="true" className="size-4" />
                Open assistant
              </Button>
            )}
          </div>
          <div className="scroll-fade-effect-y scrollbar-none relative max-h-104 min-h-0 flex-1 overflow-y-auto @3xl:max-h-none">
            <PolicyPage paragraphs={paragraphs} sweep={sweep} onSelect={setSelection} />
            {applied ? (
              <div className="sticky bottom-3 flex justify-center px-4 pb-1">
                <div className="flex items-center gap-2 rounded-full border border-border bg-popover py-1 pr-1 pl-3 text-sm text-popover-foreground shadow-md">
                  Edit applied
                  <Button size="sm" variant="secondary" className="h-7" onClick={undo}>
                    <UndoIcon aria-hidden="true" className="size-4" />
                    Undo
                  </Button>
                </div>
              </div>
            ) : null}
          </div>
        </div>

        <div
          ref={panelRef}
          inert={!open}
          className={cn(
            "min-h-0 overflow-hidden border-t border-border @3xl:border-t-0 @3xl:border-l",
            open ? "h-[34rem] @3xl:h-auto" : "@max-3xl:hidden @3xl:border-l-0",
          )}
        >
          <div
            className={cn(
              "h-full w-full @3xl:w-[22rem] motion-safe:transition-transform motion-safe:duration-300 motion-safe:ease-out",
              open ? "translate-x-0" : "translate-x-full",
            )}
          >
            <AssistantPanel
              messages={messages}
              liveId={liveId}
              shown={stream.shown}
              busy={stream.busy}
              suggestions={SUGGESTIONS}
              quote={quote}
              closeRef={closeRef}
              onClose={() => toggle(false)}
              onSuggest={(index) => ask(SUGGESTIONS[index]!.label, SUGGESTIONS[index]!.reply)}
              onSend={send}
              onStop={stop}
              onClearQuote={() => setQuote(null)}
              onApply={apply}
              onDismiss={(id) => setEditState(id, "dismissed")}
            />
          </div>
        </div>
      </div>
      <p role="status" className="sr-only">
        {status}
      </p>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

