import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { type RefObject, useId } from "react";

import { SparklesIcon, XIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { answerSize } from "../shared/answer";
import { PromptField } from "../shared/prompt-field";
import { StreamAnswer } from "../shared/stream-answer";
import { useFollowScroll } from "../shared/use-follow-scroll";
import type { PanelReply } from "./data";
import { EditCard, type EditState } from "./edit-card";
import type { PageSelection } from "./policy-page";

/** One message in the panel. */
export type PanelMessage =
  | { id: string; role: "user"; text: string; quote?: string }
  | {
      id: string;
      role: "assistant";
      reply: PanelReply;
      /** The text of the paragraph when the edit was proposed. */
      before?: string;
      editState: EditState;
      /** Set when the person stopped the reply: the number of words that arrived. */
      cut?: number;
    };

/** Props for the assistant docked beside the page. */
export interface AssistantPanelProps {
  messages: PanelMessage[];
  /** The message still arriving, and how much of it is on screen. */
  liveId: string | null;
  shown: number;
  busy: boolean;
  suggestions: { label: string }[];
  quote: PageSelection | null;
  closeRef: RefObject<HTMLButtonElement | null>;
  onClose: () => void;
  onSuggest: (index: number) => void;
  onSend: (text: string) => void;
  onStop: () => void;
  onClearQuote: () => void;
  onApply: (messageId: string) => void;
  onDismiss: (messageId: string) => void;
}

/**
 * The assistant panel: a header, the conversation or starter questions, and
 * a field that can carry a quoted passage from the page. Replies stream a
 * few words at a time, and an edit appears once its reply has arrived.
 */
export function AssistantPanel(props: AssistantPanelProps) {
  const { messages, liveId, shown, busy, suggestions, quote, closeRef } = props;
  const titleId = useId();
  const follow = useFollowScroll<HTMLDivElement>(`${messages.length}-${shown}`);

  return (
    <section aria-labelledby={titleId} className="flex h-full min-h-0 flex-col">
      <header className="flex items-center justify-between gap-2 border-b border-border px-4 py-3">
        <h3 id={titleId} className="flex items-center gap-2 text-sm font-semibold">
          <SparklesIcon aria-hidden="true" className="size-4 text-chart-1" />
          Ask about this page
        </h3>
        <Button ref={closeRef} variant="ghost" size="icon" className="size-8" aria-label="Close the assistant" onClick={props.onClose}>
          <XIcon aria-hidden="true" className="size-4" />
        </Button>
      </header>

      <div ref={follow.ref} onScroll={follow.onScroll} className="scroll-fade-effect-y scrollbar-none flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-4 py-4">
        {messages.length === 0 ? (
          <p className="text-sm text-muted-foreground">Fern reads only this page. Ask a question, or select a passage and ask about it.</p>
        ) : null}
        {messages.map((message) => {
          if (message.role === "user") {
            return (
              <div key={message.id} className="flex flex-col items-end gap-1.5 self-end">
                {message.quote ? (
                  <blockquote className="max-w-64 border-l-2 border-chart-2 pl-2 text-xs text-muted-foreground">
                    <p className="line-clamp-2">{message.quote}</p>
                  </blockquote>
                ) : null}
                <p className="max-w-64 rounded-2xl rounded-br-md bg-muted px-3 py-2 text-sm">{message.text}</p>
              </div>
            );
          }
          const live = message.id === liveId;
          const total = answerSize(message.reply.parts);
          const on = live ? shown : (message.cut ?? total);
          const complete = on >= total;
          return (
            <div key={message.id} className="flex flex-col gap-3">
              {on === 0 && live ? <p className="text-sm text-muted-foreground motion-safe:animate-pulse">Reading the page</p> : null}
              <StreamAnswer parts={message.reply.parts} shown={on} live={live} />
              {message.cut !== undefined && !complete ? <p className="text-xs text-muted-foreground">Stopped</p> : null}
              {message.reply.edit && message.before !== undefined && complete ? (
                <EditCard
                  before={message.before}
                  after={message.reply.edit.after}
                  state={message.editState}
                  onApply={() => props.onApply(message.id)}
                  onDismiss={() => props.onDismiss(message.id)}
                />
              ) : null}
            </div>
          );
        })}
      </div>

      <div className="flex flex-col gap-2 px-4 pt-1 pb-4">
        <ul aria-label="Suggested questions" className="flex flex-wrap gap-1.5">
          {suggestions.map((suggestion, index) => (
            <li key={suggestion.label}>
              <Button variant="outline" size="sm" className="h-7" disabled={busy} onClick={() => props.onSuggest(index)}>
                {suggestion.label}
              </Button>
            </li>
          ))}
        </ul>
        <PromptField
          label="Ask about this page"
          placeholder={quote ? "Ask about the selected passage" : "Ask about this page"}
          busy={busy}
          onSend={props.onSend}
          onStop={props.onStop}
          context={
            quote ? (
              <div className={cn("flex items-start gap-2 rounded-lg border-l-2 border-chart-2 py-1 pr-1 pl-2")}>
                <p className="line-clamp-2 min-w-0 flex-1 text-xs text-muted-foreground">{quote.text}</p>
                <Button variant="ghost" size="icon" className="size-6" aria-label="Remove the selected passage" onClick={props.onClearQuote}>
                  <XIcon aria-hidden="true" className="size-3.5" />
                </Button>
              </div>
            ) : null
          }
        />
      </div>
    </section>
  );
}

/** One block of a formatted reply. Inline `code` and citations like [2] live inside the text. */
export type AnswerPart =
  | { kind: "p"; text: string }
  | { kind: "h"; text: string }
  | { kind: "steps"; items: string[] }
  | { kind: "bullets"; items: string[] }
  | { kind: "code"; label: string; text: string }
  | { kind: "table"; head: string[]; rows: string[][] };

/** Splits a run of text into the words a stream reveals one group at a time. */
export const words = (text: string) => text.split(/\s+/).filter(Boolean);

/** How many stream steps one part takes: a word of text, a line of code or a row of a table. */
export function partSize(part: AnswerPart): number {
  switch (part.kind) {
    case "p":
    case "h":
      return words(part.text).length;
    case "steps":
    case "bullets":
      return part.items.reduce((sum, item) => sum + words(item).length, 0);
    case "code":
      return part.text.split("\n").length;
    case "table":
      return part.rows.length + 1;
  }
}

/** The number of stream steps a whole reply takes. */
export const answerSize = (parts: AnswerPart[]) =>
  parts.reduce((sum, part) => sum + partSize(part), 0);

/** The reply as plain text, for Copy. */
export function answerText(parts: AnswerPart[]): string {
  return parts
    .map((part) => {
      switch (part.kind) {
        case "p":
        case "h":
          return part.text;
        case "steps":
          return part.items
            .map((item, index) => `${index + 1}. ${item}`)
            .join("\n");
        case "bullets":
          return part.items.map((item) => `- ${item}`).join("\n");
        case "code":
          return part.text;
        case "table":
          return [part.head, ...part.rows]
            .map((row) => row.join(" | "))
            .join("\n");
      }
    })
    .join("\n\n")
    .replace(/`/g, "");
}

"use client";

import { type KeyboardEvent, type ReactNode, useState } from "react";

import { ArrowUpIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

import { StopIcon } from "../icons";

/** Props for the message field at the foot of a chat. */
export interface PromptFieldProps {
  label: string;
  placeholder: string;
  /** True while a reply streams: the send button turns into stop. */
  busy: boolean;
  onSend: (text: string) => void;
  onStop: () => void;
  /** Extra controls on the left of the action row, such as attach. */
  tools?: ReactNode;
  /** Text that sits above the field, such as a quoted passage. */
  context?: ReactNode;
  className?: string;
}

/**
 * A message field that grows with its text. Enter sends, Shift and Enter adds
 * a line, and Escape stops a streaming reply.
 */
export function PromptField({
  label,
  placeholder,
  busy,
  onSend,
  onStop,
  tools,
  context,
  className,
}: PromptFieldProps) {
  const [text, setText] = useState("");
  const send = () => {
    const value = text.trim();
    if (!value || busy) return;
    onSend(value);
    setText("");
  };
  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      send();
    } else if (event.key === "Escape" && busy) {
      event.preventDefault();
      onStop();
    }
  };
  return (
    <div
      className={cn("flex flex-col gap-2", className)}
    >
      {context}
      <Textarea
        aria-label={label}
        placeholder={placeholder}
        value={text}
        rows={1}
        onChange={(event) => setText(event.target.value)}
        onKeyDown={onKeyDown}
        className="max-h-40 min-h-10 resize-none"
      />
      <div className="flex items-center gap-1">
        {tools}
        <span className="flex-1" />
        {busy ? (
          <Button
            size="icon"
            variant="secondary"
            className="size-8"
            aria-label="Stop the reply"
            onClick={onStop}
          >
            <StopIcon aria-hidden="true" className="size-3.5" />
          </Button>
        ) : (
          <Button
            size="icon"
            className="size-8"
            aria-label="Send"
            disabled={!text.trim()}
            onClick={send}
          >
            <ArrowUpIcon aria-hidden="true" className="size-4" />
          </Button>
        )}
      </div>
    </div>
  );
}

"use client";

import { ownIcon, packIcon } from "@/components/blocks/parts/icons";

/** Two sheets, for copy, from the chosen icon pack. */
export const CopyIcon = packIcon("copy");
/** A magnifier, from the chosen icon pack. */
export const SearchIcon = packIcon("search");
/** A paper clip, for attach, from the chosen icon pack. */
export const PaperclipIcon = packIcon("paperclip");
/** A share mark, from the chosen icon pack. */
export const ShareIcon = packIcon("share");
/** Three dots, for more actions, from the chosen icon pack. */
export const DotsIcon = packIcon("dots");
/** A clock, from the chosen icon pack. */
export const ClockIcon = packIcon("clock");
/** A globe, for web search, from the chosen icon pack. */
export const WebIcon = packIcon("globe");
/** A notebook, for a page, from the chosen icon pack. */
export const NotebookIcon = packIcon("notebook");
