const DONE_LABEL = { applied: "Applied to the page", dismissed: "Dismissed", undone: "Undone" } as const;

/**
 * A proposed change as a word-by-word diff: removed words struck through,
 * new words underlined, each also named for screen readers. Apply writes it
 * to the page; Dismiss leaves the page as it is.
 */
export function EditCard({ before, after, state, onApply, onDismiss }: EditCardProps) {
  const runs = diffWords(before, after);
  return (
    <div className="flex flex-col gap-3 rounded-xl border border-border p-3">
      <p className="text-sm leading-relaxed">
        {runs.map((run, index) => {
          if (run.kind === "same") return <span key={index}>{run.text} </span>;
          const removed = run.kind === "removed";
          return (
            <span key={index}>
              {removed ? <del className={cn("rounded-sm px-0.5 decoration-1", STATUS_SURFACE.bad, STATUS_TEXT.bad)}>
                <span className="sr-only">Removed: </span>
                {run.text}
              </del> : <ins className={cn("rounded-sm px-0.5 no-underline", STATUS_SURFACE.good, STATUS_TEXT.good)}>
                <span className="sr-only">Added: </span>
                {run.text}
              </ins>}{" "}
            </span>
          );
        })}
      </p>
      {state === "pending" ? (
        <div className="flex flex-wrap gap-2">
          <Button size="sm" onClick={onApply}>
            <CheckIcon aria-hidden="true" className="size-4" />
            Apply
          </Button>
          <Button size="sm" variant="outline" onClick={onDismiss}>
            <XIcon aria-hidden="true" className="size-4" />
            Dismiss
          </Button>
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">{DONE_LABEL[state]}</p>
      )}
    </div>
  );
}

