/** One run of a word diff: words both versions share, words only the old one has, or words only the new one has. */
export interface DiffRun {
  kind: "same" | "removed" | "added";
  text: string;
}

/**
 * Compares two texts word by word with a longest common subsequence and
 * returns runs of shared, removed and added words, in reading order.
 */
export function diffWords(before: string, after: string): DiffRun[] {
  const a = before.split(/\s+/).filter(Boolean);
  const b = after.split(/\s+/).filter(Boolean);
  const table = Array.from({ length: a.length + 1 }, () =>
    new Array<number>(b.length + 1).fill(0),
  );
  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) {
      table[i]![j] =
        a[i] === b[j]
          ? table[i + 1]![j + 1]! + 1
          : Math.max(table[i + 1]![j]!, table[i]![j + 1]!);
    }
  }
  const runs: DiffRun[] = [];
  const push = (kind: DiffRun["kind"], word: string) => {
    const last = runs.at(-1);
    if (last && last.kind === kind) last.text += ` ${word}`;
    else runs.push({ kind, text: word });
  };
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      push("same", a[i]!);
      i++;
      j++;
    } else if (table[i + 1]![j]! >= table[i]![j + 1]!) {
      push("removed", a[i++]!);
    } else {
      push("added", b[j++]!);
    }
  }
  while (i < a.length) push("removed", a[i++]!);
  while (j < b.length) push("added", b[j++]!);
  return runs;
}

"use client";

import { useEffect, useRef } from "react";

import { DOC_TITLE, type DocParagraph } from "./data";
import { SweepText } from "./sweep-text";

/** A passage the person selected on the page. */
export interface PageSelection {
  paragraphId: string;
  text: string;
}

/** Props for the policy page the assistant reads. */
export interface PolicyPageProps {
  paragraphs: DocParagraph[];
  /** The paragraph an edit just changed, and its text before, so the change can sweep in. */
  sweep: { paragraphId: string; before: string } | null;
  onSelect: (selection: PageSelection | null) => void;
}

/**
 * The document itself. It reports a text selection inside one paragraph,
 * clears it when the selection collapses on the page, and keeps it when
 * focus moves elsewhere, such as to the assistant.
 */
export function PolicyPage({ paragraphs, sweep, onSelect }: PolicyPageProps) {
  const ref = useRef<HTMLElement>(null);
  const report = useRef(onSelect);
  useEffect(() => {
    report.current = onSelect;
  });

  useEffect(() => {
    const onChange = () => {
      const page = ref.current;
      const selection = document.getSelection();
      if (!page || !selection || !selection.anchorNode || !page.contains(selection.anchorNode)) return;
      const text = selection.toString().trim();
      const paragraph = selection.anchorNode.parentElement?.closest<HTMLElement>("[data-paragraph]");
      if (!text || !paragraph) report.current(null);
      else report.current({ paragraphId: paragraph.dataset.paragraph ?? "", text });
    };
    document.addEventListener("selectionchange", onChange);
    return () => document.removeEventListener("selectionchange", onChange);
  }, []);

  return (
    <article ref={ref} className="mx-auto flex w-full max-w-[36rem] flex-col gap-4 px-6 py-8">
      <h3 className="text-xl font-semibold tracking-tight">{DOC_TITLE}</h3>
      <p className="text-xs text-muted-foreground">Fernhill front desk handbook, section 4</p>
      {paragraphs.map((paragraph) => (
        <p key={paragraph.id} data-paragraph={paragraph.id} className="text-sm leading-relaxed">
          {sweep?.paragraphId === paragraph.id ? <SweepText before={sweep.before} after={paragraph.text} /> : paragraph.text}
        </p>
      ))}
    </article>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { diffWords } from "../shared/word-diff";

/**
 * A paragraph just changed by an applied edit. The new words take a tint
 * that sweeps across them from the left once. With reduced motion the tint
 * simply appears.
 */
export function SweepText({ before, after }: { before: string; after: string }) {
  const reduceMotion = useReducedMotion();
  const runs = diffWords(before, after).filter((run) => run.kind !== "removed");
  return (
    <>
      {runs.map((run, index) =>
        run.kind === "same" ? (
          <span key={index}>{run.text} </span>
        ) : (
          <span key={index}>
            <motion.mark
              className="rounded-sm bg-transparent bg-linear-to-r from-chart-2/30 to-chart-2/30 bg-no-repeat box-decoration-clone text-foreground"
              initial={{ backgroundSize: reduceMotion ? "100% 100%" : "0% 100%" }}
              animate={{ backgroundSize: "100% 100%" }}
              transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1], delay: index * 0.04 }}
            >
              {run.text}
            </motion.mark>{" "}
          </span>
        ),
      )}
    </>
  );
}
